class Solution {
    private int[] arr,memo;
    private int d;
    public int maxJumps(int[] arr,int d){
        this.arr=arr;
        this.d=d;
        memo=new int[arr.length];
        int answer=0;
        for(int i=0;i<arr.length;i++)answer=Math.max(answer,dfs(i));
        return answer;
    }
    private int dfs(int index){
        if(memo[index]!=0)return memo[index];
        int best=1;
        for(int direction:new int[]{
            -1,1
        })for(int step=1;step<=d;step++){
            int next=index+direction*step;
            if(next<0||next>=arr.length||arr[next]>=arr[index])break;
            best=Math.max(best,1+dfs(next));
        }
        return memo[index]=best;
    }
}

code.kotlin:
class Solution {
    private lateinit var arr:IntArray;
    private lateinit var memo:IntArray;
    private var d=0;
    fun maxJumps(arr:IntArray,d:Int):Int{
        this.arr=arr;
        this.d=d;
        memo=IntArray(arr.size);
        return arr.indices.maxOf{
            dfs(it)
        }
    };
    private fun dfs(index:Int):Int{
        if(memo[index]!=0)return memo[index];
        var best=1;
        for(direction in intArrayOf(-1,1))for(step in 1..d){
            val next=index+direction*step;
            if(next !in arr.indices||arr[next]>=arr[index])break;
            best=maxOf(best,1+dfs(next))
        };
        memo[index]=best;
        return best
    }
}

